import { Group, Mesh, PlaneGeometry, OctahedronGeometry, DirectionalLight, AmbientLight, Color, Vector3, CylinderGeometry, CircleGeometry, DoubleSide } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uniform, vec3, mix, smoothstep, uv, time, pow, fract, sin, cos, positionLocal, output, emissive, normalLocal, float, vec2, fwidth, abs, sub, add, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'prism-refraction-node';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#101017', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.6, hex: '#12121a' },
      { at: 1, hex: '#16161d' }
    ]
  };

  const accent = new THREE.Color(colors.accent);
  const paper = new THREE.Color(colors.paper);

  // ----- Backdrop gradient plane -----
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' }
  ];
  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[Math.max(0, stops.length - 2)]?.hex ?? stops[1].hex);
  const c2 = new THREE.Color(stops[stops.length - 1].hex);

  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const v = uv().y;
  const t1 = stops[1]?.at ?? 0.6;
  const gradCol = mix(mix(vec3(c0), vec3(c1), smoothstep(0.0, t1, v)), vec3(c2), smoothstep(t1, 1.0, v));
  // subtle radial vignette + accent halo
  const cx = uv().x.sub(0.5);
  const cy = uv().y.sub(0.55);
  const d = cx.mul(cx).add(cy.mul(cy)).sqrt();
  const vignette = float(1.0).sub(smoothstep(0.35, 0.95, d)).mul(0.85).add(0.15);
  const accentHalo = smoothstep(0.55, 0.0, d).mul(0.08);
  backdropMat.colorNode = gradCol.mul(vignette).add(vec3(accent).mul(accentHalo));
  const backdrop = new Mesh(new PlaneGeometry(8, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ----- Floor / contact plane -----
  const floorMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  floorMat.colorNode = vec3(c0).mul(0.4);
  const floor = new Mesh(new PlaneGeometry(8, 3), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, -1.6, -0.5);
  group.add(floor);

  // ----- Glass prism -----
  // Equilateral triangular cross-section, side 1.2, length 1.8
  // For a 3-segment cylinder, radius = circumradius = side / sqrt(3)
  const side = 1.2;
  const length = 1.8;
  const radius = side / Math.sqrt(3); // ~0.693
  const prismGeo = new CylinderGeometry(radius, radius, length, 3, 1, true);
  // Cylinder axis is Y by default. We want horizontal axis along X.
  prismGeo.rotateZ(Math.PI / 2);

  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color(colors.paper),
    attenuationDistance: 2.5,
    side: DoubleSide,
    transparent: true,
  });
  // iridescenceThicknessRange
  if (prismMat.iridescenceThicknessRange !== undefined) {
    prismMat.iridescenceThicknessRange = [120, 480];
  } else if ('iridescenceThicknessMin' in prismMat && 'iridescenceThicknessMax' in prismMat) {
    prismMat.iridescenceThicknessMin = 120;
    prismMat.iridescenceThicknessMax = 480;
  }

  // TSL dispersion-like color split: modulate output by a chromatic shift based on
  // fresnel (view-dependent) to simulate dispersion along refracted edges.
  const nL = normalLocal.normalize();
  const viewDir = positionLocal.normalize();
  const fresnel = float(1.0).sub(abs(nL.dot(viewDir)));
  const dispAmount = float(0.18);
  // shift R/G/B channels slightly based on fresnel + subtle time shimmer
  const shimmer = sin(time.mul(0.4).add(positionLocal.y.mul(3.0))).mul(0.04);
  const t = fresnel.mul(dispAmount).add(shimmer);
  const tint = mix(
    vec3(1.0, 0.82, 0.78),          // warm red shift at high fresnel (dispersion toward red)
    vec3(0.78, 0.86, 1.0),          // cool blue shift at low fresnel
    smoothstep(0.0, 0.5, t)
  );
  // add iridescent fringe
  const iris = vec3(
    sin(time.mul(0.3).add(fresnel.mul(8.0)).add(0.0)).add(1.0).mul(0.5),
    sin(time.mul(0.3).add(fresnel.mul(8.0)).add(2.094)).add(1.0).mul(0.5),
    sin(time.mul(0.3).add(fresnel.mul(8.0)).add(4.188)).add(1.0).mul(0.5)
  );
  const iridescentFringe = iris.mul(pow(fresnel, 1.5)).mul(0.25);
  // compose emissive (so light still passes via transmission)
  prismMat.emissiveNode = iridescentFringe.mul(0.5).add(tint.mul(fresnel).mul(0.15));
  // color modulation (kept subtle so transmission still reads glass)
  prismMat.colorNode = mix(vec3(1.0), tint, fresnel.mul(0.25));

  const prismMesh = new Mesh(prismGeo, prismMat);
  prismMesh.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
  prismMesh.position.set(0, 0, 0);
  group.add(prismMesh);

  // ----- Emissive core octahedron -----
  const coreGeo = new OctahedronGeometry(0.35, 0);
  const coreMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    roughness: 0.35,
    metalness: 0.1,
    transparent: true,
  });
  coreMat.emissiveNode = vec3(accent).mul(2.2);
  const core = new Mesh(coreGeo, coreMat);
  core.position.set(0, 0, 0);
  group.add(core);

  // breathing pulse on core
  const coreTL = gsap.timeline({ repeat: -1, yoyo: true });
  coreTL.to(core.scale, { x: 1.08, y: 1.08, z: 1.08, duration: 2.4, ease: 'sine.inOut' });

  // ----- Lights -----
  // Scene provides ambient 0.6 + key 1.2. We add rim/accent lights locally.
  const rimLight = new DirectionalLight(0x9fb0c4, 1.0);
  rimLight.position.set(-2.5, 1.8, -2.5);
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  const accentRim = new DirectionalLight(accent.getHex(), 0.6);
  accentRim.position.set(2.5, -0.5, -2.0);
  accentRim.target.position.set(0, 0, 0);
  group.add(accentRim);
  group.add(accentRim.target);

  const fillLight = new AmbientLight(0x303040, 0.3);
  group.add(fillLight);

  // ----- Caustic streak on floor -----
  const causticMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  // engineered linear gradient of dispersed stops
  const u = uv().x; // along length
  const causticCol = mix(
    vec3(accent),
    mix(vec3(paper), vec3(0x9fb0c4), smoothstep(0.5, 0.8, u)),
    smoothstep(0.2, 0.5, u)
  );
  // elongation shimmer 8% when prism tilts (faux): drive a time-based stretch via uv remap
  const stretch = sin(time.mul(0.5)).mul(0.04).add(1.0); // ±4% shimmer
  const uu = u.sub(0.5).mul(stretch).add(0.5);
  const streakAlpha = smoothstep(0.0, 0.15, uu).mul(smoothstep(1.0, 0.85, uu)).mul(0.35);
  // taper along v (vertical falloff)
  const vv = uv().y;
  const vFade = smoothstep(0.0, 0.5, vv).mul(smoothstep(1.0, 0.5, vv));
  causticMat.colorNode = causticCol;
  causticMat.opacityNode = streakAlpha.mul(vFade);
  if (causticMat.transparent !== undefined) causticMat.transparent = true;
  causticMat.depthWrite = false;
  const caustic = new Mesh(new PlaneGeometry(2.4, 0.5), causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.4);
  group.add(caustic);

  // ----- Contact shadow under prism -----
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const su = uv().sub(0.5);
  const sd = su.length();
  shadowMat.colorNode = vec3(0.0);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, sd).mul(0.55);
  const shadowPlane = new Mesh(new CircleGeometry(1.4, 48), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.59, 0);
  group.add(shadowPlane);

  // ----- Text content -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const role = item.role;
    let fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : 18);
    // scale pixel-specified font sizes down to scene units
    fontSize = fontSize / 100; // 0.68 / 0.18
    let color = role === 'headline' ? colors.paper : colors.paper;
    const align = role === 'headline' ? 'center' : 'center';
    const letterSpacing = role === 'headline' ? -0.005 : 0.08;
    const tm = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align,
      letterSpacingPx: letterSpacing * fontSize * 100,
    });
    if (role === 'headline') {
      tm.position.set(0, -1.75, 0.1);
    } else {
      tm.position.set(0, -2.25, 0.1);
      // caption all-caps letter spacing already handled
    }
    textMeshes.push(tm);
    group.add(tm);
  }

  // ----- Cinematic primitive: depth-rotate on hover -----
  const primitives = [];
  const cps = config.cinematicPrimitives ?? [];
  for (const p of cps) {
    if (!p || !p.name) continue;
    const target = p.name === 'depth-rotate' ? prismMesh : group;
    const res = ctx.primitives[p.name](target, p.params ?? {});
    if (res) primitives.push(res);
  }

  // ----- Entrance animation -----
  const entranceTL = gsap.timeline();
  entranceTL.from(group.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTL.from(group.rotation, { z: 0.05, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTL.from(textMeshes.map(m => m.position), { y: '+=0.3', autoAlpha: 0, duration: 0.5, ease: 'power2.out', stagger: 0.08 }, 0.15);
  // weighted-settle on prism
  entranceTL.from(prismMesh.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' }, 0.1);

  // ----- Hover handlers -----
  group.userData.handlers = {
    pointerenter: () => {
      gsap.to(prismMesh.rotation, {
        x: THREE.MathUtils.degToRad(10),
        duration: 0.35,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        overwrite: true,
      });
    },
    pointerleave: () => {
      gsap.to(prismMesh.rotation, {
        x: 0,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: true,
      });
    },
    click: () => {
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  // ----- Cleanup -----
  group.userData.cleanup = () => {
    entranceTL.kill();
    coreTL.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(prismMesh.rotation);
    gsap.killTweensOf(prismMesh.scale);
    for (const p of primitives) {
      try { p.cleanup?.(); } catch (e) {}
    }
    backdropMat.dispose();
    floorMat.dispose();
    prismMat.dispose();
    coreMat.dispose();
    causticMat.dispose();
    shadowMat.dispose();
    prismGeo.dispose();
    coreGeo.dispose();
    backdrop.geometry.dispose();
    floor.geometry.dispose();
    caustic.geometry.dispose();
    shadowPlane.geometry.dispose();
  };

  return group;
}
